"use client";

import * as React from "react";

import {
  formatMobile,
  type MobileResult,
  validateMobile,
} from "../../lib/mobile";
import { cn, controlClasses, Field, useFieldState } from "./field";

export interface MobileInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: MobileResult) => void;
  validateOn?: "blur" | "change";
  /** Show a non-editable +91 prefix. Default `true`. */
  showCountryCode?: boolean;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function MobileInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showCountryCode = true,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: MobileInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `mobile-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<MobileResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validateMobile,
    // normalizeMobile inside formatMobile strips a pasted +91/0 prefix, so
    // pasting a number in any common shape just works.
    transform: formatMobile,
    validateOn,
  });

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        {showCountryCode && (
          <span
            aria-hidden
            className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 border-r border-neutral-300 pr-2 font-mono text-sm text-neutral-500 dark:border-neutral-700 dark:text-neutral-400"
          >
            +91
          </span>
        )}
        <input
          {...props}
          id={inputId}
          type="tel"
          inputMode="numeric"
          autoComplete="tel-national"
          placeholder={props.placeholder ?? "98765 43210"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            "tracking-[0.1em]",
            showCountryCode && "pl-16",
            className,
          )}
        />
      </div>
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Indian mobile number validation.
 *
 * Ten digits starting 6–9. Anything shorter is a landline, a short code, or a
 * typo. We accept and strip the prefixes people actually paste — `+91`, `0091`,
 * a leading `0`, spaces, dashes and brackets — because rejecting a correct
 * number over formatting is the rudest thing a form can do.
 */

const MOBILE_RE = /^[6-9]\d{9}$/;

export type MobileErrorCode =
  | "empty"
  | "not_digits"
  | "too_short"
  | "too_long"
  | "bad_leading_digit";

export interface MobileResult {
  valid: boolean;
  /** Ten digits, no country code. */
  normalized: string;
  /** `+919876543210` — what most SMS/OTP APIs want. */
  e164?: string;
  /** `98765 43210` — how Indians actually read a number out. */
  formatted?: string;
  error?: { code: MobileErrorCode; message: string };
}

function fail(
  code: MobileErrorCode,
  message: string,
  normalized: string,
): MobileResult {
  return { valid: false, normalized, error: { code, message } };
}

/** Strip country codes, trunk prefix and separators down to ten digits. */
export function normalizeMobile(input: string): string {
  let digits = input.replace(/\D/g, "");
  if (digits.startsWith("0091")) digits = digits.slice(4);
  else if (digits.startsWith("91") && digits.length > 10)
    digits = digits.slice(2);
  if (digits.startsWith("0") && digits.length > 10) digits = digits.slice(1);
  return digits;
}

/** `9876543210` → `98765 43210`. */
export function formatMobile(input: string): string {
  const digits = normalizeMobile(input);
  if (digits.length <= 5) return digits;
  return `${digits.slice(0, 5)} ${digits.slice(5, 10)}`;
}

export function validateMobile(input: string): MobileResult {
  const digits = normalizeMobile(input);

  if (!input.trim()) return fail("empty", "Enter a mobile number.", digits);
  if (/[^\d\s+\-()]/.test(input)) {
    return fail("not_digits", "A mobile number is digits only.", digits);
  }
  if (digits.length < 10) {
    return fail(
      "too_short",
      `Indian mobile numbers are 10 digits — ${digits.length} so far.`,
      digits,
    );
  }
  if (digits.length > 10) {
    return fail(
      "too_long",
      "That's more than 10 digits. Drop the country code.",
      digits,
    );
  }
  if (!MOBILE_RE.test(digits)) {
    return fail(
      "bad_leading_digit",
      "An Indian mobile number starts with 6, 7, 8 or 9.",
      digits,
    );
  }

  return {
    valid: true,
    normalized: digits,
    e164: `+91${digits}`,
    formatted: formatMobile(digits),
  };
}
